"""Emit src/gauge/gradient-stops.ts from the sampled speedtest.net gauge gradient assets."""
import json, os

BASE = r"C:\oss\Project\speedtest"
data = json.load(open(os.path.join(BASE, "research", "gradient-samples.json")))

lines = [
    "// AUTO-GENERATED by tools/emit_stops.py — do not edit by hand.",
    "//",
    "// Colour look-up tables sampled along the arc mid-radius of the gauge gradient",
    "// assets that speedtest.net ships (gauge-gradient-{dl,ul}-{multi,single}-web.png).",
    "// Sampling proved the colour is radially invariant (identical at r=100..150 for a",
    "// given angle), so the arc can be reproduced exactly as an angular gradient.",
    "",
    "export interface GradientStop {",
    "  /** 0 = arc start (-135 deg), 1 = arc end (+135 deg). */",
    "  t: number;",
    "  hex: string;",
    "}",
    "",
    "export const GRADIENT_STOPS: Record<string, GradientStop[]> = {",
]

for key in ("dl-multi", "ul-multi", "dl-single", "ul-single"):
    lines.append(f'  "{key}": [')
    for s in data[key]["arc"]:
        lines.append(f'    {{ t: {s["t"]:.4f}, hex: "{s["hex"]}" }},')
    lines.append("  ],")
lines.append("};")
lines.append("")

out = os.path.join(BASE, "src", "gauge", "gradient-stops.ts")
os.makedirs(os.path.dirname(out), exist_ok=True)
open(out, "w", encoding="utf-8").write("\n".join(lines))
print("wrote", out, len(lines), "lines")
